    @Test
    void acceptsExactlyOneKindOfIdentification() throws Exception {
        String base = RESERVATION_JSON.replace("\"guestCpf\": \"111.222.333-44\", ", "");
        String company = base.replace("{", "{\"companyCnpj\": \"12.345.678/0001-90\", \"companyName\": \"Tecnosul\", ");
